#!/bin/sh
# Xcode Cloud (S23) runs this right after cloning. The Xcode project is generated by XcodeGen and isn't in git,
# so make it here, before Xcode Cloud looks for DayXero.xcodeproj.
set -e
cd "$CI_PRIMARY_REPOSITORY_PATH"

brew install xcodegen
xcodegen generate

# Xcode Cloud won't resolve Swift packages by itself without a Package.resolved, so resolve them now.
xcodebuild -resolvePackageDependencies -project DayXero.xcodeproj -scheme DayXero

# Analytics key for Release builds, from the workflow's secret POSTHOG_API_KEY (as the GitHub upload does).
if [ -n "$POSTHOG_API_KEY" ]; then
  {
    echo "DX_POSTHOG_API_KEY_RELEASE = $POSTHOG_API_KEY"
    echo 'DX_POSTHOG_HOST = https:/$()/us.i.posthog.com'
  } > Config/Secrets.xcconfig
fi
